contracts/AuralisAgentRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title AuralisAgentRegistry
/// @author Auralis Finance
/// @notice Soulbound (non-transferable) identity for Auralis AI agents/operators.
/// @dev    Designed to interoperate with Mantle's ERC-8004 agent-identity standard:
///         `erc8004Ref` cross-references the Mantle-issued agent id when available.
///         If ERC-8004 is unavailable at deploy time, this registry stands alone as
///         the canonical Auralis agent identity. Agent REPUTATION (ratings anchored,
///         attestations minted, decisions logged) is derived off-chain by indexing
///         AuralisRatingRegistry / AuralisComplianceAttestor events — keeping this
///         contract decoupled and free of fragile cross-contract calls.
contract AuralisAgentRegistry is ERC721, Ownable {
    // ----------------------------------------------------------------------
    // Types
    // ----------------------------------------------------------------------

    struct AgentProfile {
        string name;
        string metadataURI; // ipfs:// agent card (capabilities, skills, version)
        uint64 registeredAt;
        bool active;
        uint256 erc8004Ref; // Mantle ERC-8004 id cross-ref (0 if none)
    }

    // ----------------------------------------------------------------------
    // Storage
    // ----------------------------------------------------------------------

    uint256 public nextTokenId = 1;
    mapping(uint256 => AgentProfile) public agents;
    mapping(uint256 => string) private _tokenURIs;
    mapping(address => bool) public approvedMinters;

    // ----------------------------------------------------------------------
    // Events
    // ----------------------------------------------------------------------

    event AgentRegistered(
        uint256 indexed tokenId,
        address indexed operator,
        string name,
        uint256 erc8004Ref
    );
    event AgentMetadataUpdated(uint256 indexed tokenId, string metadataURI);
    event AgentActiveSet(uint256 indexed tokenId, bool active);
    event MinterUpdated(address indexed minter, bool approved);

    // ----------------------------------------------------------------------
    // Constructor
    // ----------------------------------------------------------------------

    constructor(
        address initialOwner
    ) ERC721("Auralis Agent Identity", "AURA-AGENT") Ownable(initialOwner) {}

    // ----------------------------------------------------------------------
    // Modifiers
    // ----------------------------------------------------------------------

    modifier onlyMinter() {
        require(
            msg.sender == owner() || approvedMinters[msg.sender],
            "AURALIS: not minter"
        );
        _;
    }

    // ----------------------------------------------------------------------
    // Admin
    // ----------------------------------------------------------------------

    function setMinter(address minter, bool approved) external onlyOwner {
        approvedMinters[minter] = approved;
        emit MinterUpdated(minter, approved);
    }

    // ----------------------------------------------------------------------
    // Core
    // ----------------------------------------------------------------------

    /// @notice Register (mint) a soulbound agent identity to an operator wallet.
    function registerAgent(
        address operator,
        string calldata name,
        string calldata metadataURI,
        uint256 erc8004Ref
    ) external onlyMinter returns (uint256 tokenId) {
        require(operator != address(0), "AURALIS: zero operator");
        require(bytes(name).length != 0, "AURALIS: empty name");

        tokenId = nextTokenId++;
        _safeMint(operator, tokenId);
        _tokenURIs[tokenId] = metadataURI;
        agents[tokenId] = AgentProfile({
            name: name,
            metadataURI: metadataURI,
            registeredAt: uint64(block.timestamp),
            active: true,
            erc8004Ref: erc8004Ref
        });

        emit AgentRegistered(tokenId, operator, name, erc8004Ref);
    }

    function updateMetadata(
        uint256 tokenId,
        string calldata metadataURI
    ) external {
        require(
            ownerOf(tokenId) == msg.sender || msg.sender == owner(),
            "AURALIS: not authorized"
        );
        agents[tokenId].metadataURI = metadataURI;
        _tokenURIs[tokenId] = metadataURI;
        emit AgentMetadataUpdated(tokenId, metadataURI);
    }

    function setActive(uint256 tokenId, bool active) external {
        require(
            ownerOf(tokenId) == msg.sender || msg.sender == owner(),
            "AURALIS: not authorized"
        );
        agents[tokenId].active = active;
        emit AgentActiveSet(tokenId, active);
    }

    // ----------------------------------------------------------------------
    // Views
    // ----------------------------------------------------------------------

    function tokenURI(
        uint256 tokenId
    ) public view override returns (string memory) {
        _requireOwned(tokenId);
        return _tokenURIs[tokenId];
    }

    // ----------------------------------------------------------------------
    // Soulbound enforcement
    // ----------------------------------------------------------------------

    /// @dev Allow mint (from == 0) and burn (to == 0); block all transfers.
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override returns (address from) {
        from = _ownerOf(tokenId);
        if (from != address(0) && to != address(0)) {
            revert("AURALIS: soulbound");
        }
        return super._update(to, tokenId, auth);
    }
}

contracts/AuralisComplianceAttestor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";

/// @title AuralisComplianceAttestor
/// @author Auralis Finance
/// @notice Issues privacy-preserving, reusable compliance / eligibility attestations
///         for tokenized real-world assets on Mantle.
/// @dev    Only the verdict + content-addressed check hash are written on-chain.
///         The compliance check INPUTS (jurisdiction declaration, screening data)
///         stay private off-chain. The attestation is consumable by any Mantle app
///         via `isEligible()` — e.g. an RWA issuer can gate a purchase on it.
///
///         This is compliance TOOLING, not legal advice. Verdicts are informational.
contract AuralisComplianceAttestor is Ownable, Pausable {
    // ----------------------------------------------------------------------
    // Types
    // ----------------------------------------------------------------------

    enum Verdict {
        None,
        Eligible,
        Restricted,
        Denied
    }

    struct Attestation {
        address subject; // wallet the attestation is about
        address attester; // who minted it (subject self-attest, or approved attester)
        bytes32 assetClassId; // e.g. keccak256("US_TREASURY_RWA")
        Verdict verdict;
        bytes32 checkHash; // keccak256 of the canonical off-chain compliance check
        bytes32 jurisdictionTag; // e.g. keccak256("NG")
        string metadataURI; // ipfs:// URI of the full compliance report
        uint64 issuedAt;
        uint64 validUntil;
        bool revoked;
    }

    // ----------------------------------------------------------------------
    // Storage
    // ----------------------------------------------------------------------

    uint256 public nextAttestationId = 1;
    uint256 public mintFee; // optional, in wei (MNT)

    mapping(uint256 => Attestation) public attestations;
    mapping(address => mapping(bytes32 => uint256)) public latestAttestationOf; // subject => assetClass => id
    mapping(address => bool) public approvedAttesters;
    mapping(bytes32 => bool) public checkHashUsed;

    // ----------------------------------------------------------------------
    // Events
    // ----------------------------------------------------------------------

    event AttestationMinted(
        uint256 indexed id,
        address indexed subject,
        bytes32 indexed assetClassId,
        Verdict verdict,
        address attester,
        uint64 validUntil,
        string metadataURI
    );
    event AttestationRevoked(uint256 indexed id, address indexed by);
    event AttesterUpdated(address indexed attester, bool approved);
    event MintFeeUpdated(uint256 fee);

    // ----------------------------------------------------------------------
    // Constructor
    // ----------------------------------------------------------------------

    constructor(address initialOwner) Ownable(initialOwner) {}

    // ----------------------------------------------------------------------
    // Admin
    // ----------------------------------------------------------------------

    function setAttester(address attester, bool approved) external onlyOwner {
        approvedAttesters[attester] = approved;
        emit AttesterUpdated(attester, approved);
    }

    function setMintFee(uint256 fee) external onlyOwner {
        mintFee = fee;
        emit MintFeeUpdated(fee);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function withdraw(address to) external onlyOwner {
        require(to != address(0), "AURALIS: zero to");
        (bool ok, ) = to.call{value: address(this).balance}("");
        require(ok, "AURALIS: withdraw failed");
    }

    // ----------------------------------------------------------------------
    // Core
    // ----------------------------------------------------------------------

    /// @notice Mint a compliance attestation. The subject may self-attest, or an
    ///         approved attester (the Auralis issuer service) may attest for them.
    /// @dev    Validity is bounded to [1 hour, 365 days]. Optional mint fee is the
    ///         only value this contract ever handles.
    function mintAttestation(
        address subject,
        bytes32 assetClassId,
        Verdict verdict,
        bytes32 checkHash,
        bytes32 jurisdictionTag,
        string calldata metadataURI,
        uint64 validitySeconds
    ) external payable whenNotPaused returns (uint256 id) {
        require(subject != address(0), "AURALIS: zero subject");
        require(assetClassId != bytes32(0), "AURALIS: empty class");
        require(verdict != Verdict.None, "AURALIS: bad verdict");
        require(checkHash != bytes32(0), "AURALIS: empty check");
        require(
            msg.sender == subject || approvedAttesters[msg.sender],
            "AURALIS: not authorized"
        );
        require(msg.value >= mintFee, "AURALIS: fee too low");
        require(
            validitySeconds >= 1 hours && validitySeconds <= 365 days,
            "AURALIS: bad validity"
        );

        id = nextAttestationId++;
        uint64 validUntil = uint64(block.timestamp) + validitySeconds;

        attestations[id] = Attestation({
            subject: subject,
            attester: msg.sender,
            assetClassId: assetClassId,
            verdict: verdict,
            checkHash: checkHash,
            jurisdictionTag: jurisdictionTag,
            metadataURI: metadataURI,
            issuedAt: uint64(block.timestamp),
            validUntil: validUntil,
            revoked: false
        });
        latestAttestationOf[subject][assetClassId] = id;
        checkHashUsed[checkHash] = true;

        emit AttestationMinted(
            id,
            subject,
            assetClassId,
            verdict,
            msg.sender,
            validUntil,
            metadataURI
        );
    }

    /// @notice Revoke an attestation. Callable by subject, attester, or owner.
    function revoke(uint256 id) external {
        Attestation storage a = attestations[id];
        require(a.subject != address(0), "AURALIS: not found");
        require(
            msg.sender == a.subject ||
                msg.sender == a.attester ||
                msg.sender == owner(),
            "AURALIS: not authorized"
        );
        require(!a.revoked, "AURALIS: already revoked");
        a.revoked = true;
        emit AttestationRevoked(id, msg.sender);
    }

    // ----------------------------------------------------------------------
    // Views — consumable by any Mantle app
    // ----------------------------------------------------------------------

    /// @notice Cheap boolean eligibility read for integrators.
    function isEligible(
        address wallet,
        bytes32 assetClassId
    ) external view returns (bool) {
        uint256 id = latestAttestationOf[wallet][assetClassId];
        if (id == 0) return false;
        Attestation memory a = attestations[id];
        return
            a.verdict == Verdict.Eligible &&
            !a.revoked &&
            a.validUntil > block.timestamp;
    }

    /// @notice Full verdict read with an active flag.
    function getVerdict(
        address wallet,
        bytes32 assetClassId
    ) external view returns (Verdict verdict, bool active) {
        uint256 id = latestAttestationOf[wallet][assetClassId];
        if (id == 0) return (Verdict.None, false);
        Attestation memory a = attestations[id];
        active = !a.revoked && a.validUntil > block.timestamp;
        verdict = a.verdict;
    }
}

contracts/AuralisPolicyGuard.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.24;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";

/// @title AuralisPolicyGuard
/// @author Auralis Finance
/// @notice Per-user, on-chain portfolio guardrails for AI-proposed RWA rebalances.
/// @dev    SAFETY MODEL: the AI only ever *proposes* a rebalance. This contract
///         deterministically *enforces* the user's guardrails and REVERTS on any
///         breach. There is NO autonomous execution path — `executeRebalance` is
///         reachable only via a user-signed transaction from the policy owner.
///         The contract holds no funds and no keys. This is the structural answer
///         to "the agent must never be able to run away with capital."
contract AuralisPolicyGuard is Ownable {
    // ----------------------------------------------------------------------
    // Types
    // ----------------------------------------------------------------------

    struct Policy {
        uint16 maxPerAssetBps; // e.g. 2500 == 25%
        uint16 maxPerProtocolBps; // e.g. 3000 == 30%
        uint16 maxSlippageBps; // e.g. 50 == 0.50%
        uint8 minConfidence; // 0..100 minimum AI confidence
        uint16 minLiquidityScore; // 0..100 minimum liquidity score
        uint32 cooldownSeconds; // minimum time between rebalances
        uint256 humanApprovalThreshold; // notional above which off-chain sign-off is expected
        bool exists;
        bool paused;
    }

    struct RebalanceParams {
        bytes32 portfolioHash; // hash of the proposed target allocation
        uint16 topAssetBps; // largest single-asset weight in the proposal
        uint16 topProtocolBps; // largest single-protocol weight in the proposal
        uint16 slippageBps; // estimated slippage of the proposed route
        uint8 aiConfidence; // AI confidence in the proposal (0..100)
        uint16 liquidityScore; // blended liquidity score of the proposal (0..100)
        uint256 notionalValue; // total value affected by the rebalance
        string metadataURI; // ipfs:// URI of the full proposal
    }

    // ----------------------------------------------------------------------
    // Storage
    // ----------------------------------------------------------------------

    mapping(address => Policy) public policyOf;
    mapping(address => uint64) public lastRebalanceAt;
    uint256 public nextRebalanceId = 1;

    // ----------------------------------------------------------------------
    // Events
    // ----------------------------------------------------------------------

    event PolicyUpdated(address indexed user);
    event PolicyPausedSet(address indexed user, bool paused);
    event RebalanceExecuted(
        uint256 indexed id,
        address indexed user,
        bytes32 portfolioHash,
        uint256 notionalValue,
        string metadataURI
    );
    event RebalanceBlocked(address indexed user, string reason);

    // ----------------------------------------------------------------------
    // Constructor
    // ----------------------------------------------------------------------

    constructor(address initialOwner) Ownable(initialOwner) {}

    // ----------------------------------------------------------------------
    // Policy management — each user owns and signs for their own policy
    // ----------------------------------------------------------------------

    function setPolicy(
        uint16 maxPerAssetBps,
        uint16 maxPerProtocolBps,
        uint16 maxSlippageBps,
        uint8 minConfidence,
        uint16 minLiquidityScore,
        uint32 cooldownSeconds,
        uint256 humanApprovalThreshold
    ) external {
        require(
            maxPerAssetBps <= 10000 && maxPerProtocolBps <= 10000,
            "AURALIS: bad bps"
        );
        require(maxSlippageBps <= 1000, "AURALIS: slippage too high");
        require(
            minConfidence <= 100 && minLiquidityScore <= 100,
            "AURALIS: bad range"
        );

        policyOf[msg.sender] = Policy({
            maxPerAssetBps: maxPerAssetBps,
            maxPerProtocolBps: maxPerProtocolBps,
            maxSlippageBps: maxSlippageBps,
            minConfidence: minConfidence,
            minLiquidityScore: minLiquidityScore,
            cooldownSeconds: cooldownSeconds,
            humanApprovalThreshold: humanApprovalThreshold,
            exists: true,
            paused: false
        });
        emit PolicyUpdated(msg.sender);
    }

    /// @notice Emergency pause — blocks all rebalances under the caller's policy.
    function setPaused(bool paused) external {
        require(policyOf[msg.sender].exists, "AURALIS: no policy");
        policyOf[msg.sender].paused = paused;
        emit PolicyPausedSet(msg.sender, paused);
    }

    // ----------------------------------------------------------------------
    // Checks & execution
    // ----------------------------------------------------------------------

    /// @notice Pure view check — powers the live policy-preview UI before signing.
    /// @return ok true if the proposal passes every guardrail
    /// @return reason human-readable failure reason ("ok" when passing)
    function checkRebalance(
        address user,
        RebalanceParams calldata p
    ) public view returns (bool ok, string memory reason) {
        Policy memory pol = policyOf[user];
        if (!pol.exists) return (false, "no policy set");
        if (pol.paused) return (false, "policy paused");
        if (p.topAssetBps > pol.maxPerAssetBps)
            return (false, "max per-asset exceeded");
        if (p.topProtocolBps > pol.maxPerProtocolBps)
            return (false, "max per-protocol exceeded");
        if (p.slippageBps > pol.maxSlippageBps)
            return (false, "slippage limit exceeded");
        if (p.aiConfidence < pol.minConfidence)
            return (false, "AI confidence too low");
        if (p.liquidityScore < pol.minLiquidityScore)
            return (false, "liquidity too low");
        if (block.timestamp < lastRebalanceAt[user] + pol.cooldownSeconds)
            return (false, "rebalance cooldown active");
        return (true, "ok");
    }

    /// @notice Execute a guardrail-checked rebalance. USER-SIGNED ONLY.
    /// @dev    Reverts if any guardrail is breached, recording a RebalanceBlocked
    ///         event first. On success, records the rebalance on-chain as proof.
    ///         Fund routing to whitelisted Mantle venues (Aave, Merchant Moe) is a
    ///         deliberate post-hackathon, audited extension — the hackathon build
    ///         proves the *decision and its guardrail compliance* on-chain.
    function executeRebalance(
        RebalanceParams calldata p
    ) external returns (uint256 rebalanceId) {
        (bool ok, string memory reason) = checkRebalance(msg.sender, p);
        if (!ok) {
            emit RebalanceBlocked(msg.sender, reason);
            revert(string.concat("AURALIS: ", reason));
        }

        lastRebalanceAt[msg.sender] = uint64(block.timestamp);
        rebalanceId = nextRebalanceId++;

        emit RebalanceExecuted(
            rebalanceId,
            msg.sender,
            p.portfolioHash,
            p.notionalValue,
            p.metadataURI
        );
    }
}

